INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2081QCC', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A survey of 200 employees found that 74 commute by car, 53 commute by train, and 29 commute by both car and train. If an employee who commutes by car is selected at random, what is the probability that this employee also commutes by train?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{29}{200}$"},{"key":"B","text":"$\\frac{29}{74}$"},{"key":"C","text":"$\\frac{29}{53}$"},{"key":"D","text":"$\\frac{53}{74}$"}]$lyceon_json$::jsonb, 'B', NULL, E'This is a conditional probability question: given that the employee commutes by car, find the probability they also commute by train. Of the 74 car commuters, 29 also commute by train, so the probability is $\\frac{29}{74}$. The answer $\\frac{29}{200}$ incorrectly uses the total number of employees as the denominator instead of conditioning on car commuters. The answer $\\frac{29}{53}$ uses the number of train commuters as the denominator. The answer $\\frac{53}{74}$ uses the total number of train commuters in the numerator rather than only those who also commute by car.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20NYOFN', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'mcq', E'What is the solution $(x, y)$ to the system of equations below?$$\\begin{cases} 4x + 3y = 29 \\\\ x - y = 2 \\end{cases}$$', NULL, $lyceon_json$[{"key":"A","text":"$(5, 3)$"},{"key":"B","text":"$(3, 5)$"},{"key":"C","text":"$(7, -1)$"},{"key":"D","text":"$(5, -3)$"}]$lyceon_json$::jsonb, 'A', NULL, E'From the second equation, $x = y + 2$. Substituting into the first equation: $4(y + 2) + 3y = 29$, which simplifies to $4y + 8 + 3y = 29$, then $7y = 21$, so $y = 3$. Back-substituting gives $x = 3 + 2 = 5$. The solution is $(5, 3)$. The pair $(3, 5)$ reverses the $x$ and $y$ values. The pair $(7, -1)$ results from an arithmetic error when combining terms. The pair $(5, -3)$ applies an incorrect sign to $y$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21NMWWW', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $PQR$, side $PQ$ is extended through $Q$ to point $S$. If $\\angle QPR = 47°$ and $\\angle PQR = 68°$, what is the measure of the exterior angle $\\angle RQS$?', NULL, $lyceon_json$[{"key":"A","text":"$65°$"},{"key":"B","text":"$112°$"},{"key":"C","text":"$115°$"},{"key":"D","text":"$133°$"}]$lyceon_json$::jsonb, 'B', NULL, E'The exterior angle $\\angle RQS$ at vertex $Q$ is supplementary to the interior angle $\\angle PQR$, so $\\angle RQS = 180° - 68° = 112°$. Equivalently, by the Exterior Angle Theorem, $\\angle RQS$ equals the sum of the two non-adjacent interior angles: $\\angle QPR + \\angle PRQ = 47° + 65° = 112°$, where $\\angle PRQ = 180° - 47° - 68° = 65°$. The distractor $65°$ is the third interior angle of the triangle, not the exterior angle. The distractor $115°$ results from incorrectly adding $47° + 68° = 115°$, using the adjacent interior angle instead of the remote ones. The distractor $133°$ comes from an erroneous setup such as $180° - 47° = 133°$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21NWPPK', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'If $f(x) = 11x - 23$, what is the value of $f(4)$?', NULL, $lyceon_json$[{"key":"A","text":"$67$"},{"key":"B","text":"$21$"},{"key":"C","text":"$-21$"},{"key":"D","text":"$44$"}]$lyceon_json$::jsonb, 'B', NULL, E'Substituting $x = 4$ into the function: $f(4) = 11(4) - 23 = 44 - 23 = 21$. The value $-21$ results from incorrectly applying a negative sign. The value $44$ comes from computing $11 \\times 4$ but forgetting to subtract $23$. The value $67$ comes from adding $23$ instead of subtracting it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2342TI0', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'A town''s population increased by $12\\%$ from $2020$ to $2022$, reaching $8{,}960$ residents. What was the population in $2020$?', NULL, $lyceon_json$[{"key":"A","text":"$7{,}893$"},{"key":"B","text":"$7{,}886$"},{"key":"C","text":"$8{,}000$"},{"key":"D","text":"$7{,}500$"}]$lyceon_json$::jsonb, 'C', NULL, E'Let $P$ be the original population. Then $1.12P = 8{,}960$, so $P = \\frac{8{,}960}{1.12} = 8{,}000$. The value $7{,}893$ results from a rounding error during division. The value $7{,}886$ comes from subtracting $12\\%$ of $8{,}960$ (i.e., $8{,}960 - 1{,}075.2 = 7{,}884.8$, rounded to $7{,}886$) instead of dividing by $1.12$. The value $7{,}500$ reflects a guess that does not satisfy the relationship.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23JPSKH', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A cylindrical water tank has a diameter of $6$ feet and a height of $14$ feet. Water fills the tank to $\\frac{3}{7}$ of its height. A solid sphere with diameter $4$ feet is then fully submerged in the water. By how many feet does the water level rise? (Assume the sphere fits entirely within the tank.)', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{32}{27}$"},{"key":"B","text":"$\\frac{32}{27\\pi}$"},{"key":"C","text":"$\\frac{16}{27}$"},{"key":"D","text":"$\\frac{32}{9\\pi}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The sphere has radius $2$ feet, so its volume is $V_{\\text{sphere}} = \\frac{4}{3}\\pi(2)^3 = \\frac{32\\pi}{3}$ cubic feet. The cylindrical tank has radius $3$ feet, so the cross-sectional area is $A = \\pi(3)^2 = 9\\pi$ square feet. The rise in water level equals the sphere''s volume divided by the tank''s cross-sectional area: $\\Delta h = \\frac{32\\pi/3}{9\\pi} = \\frac{32}{27}$ feet. The $\\pi$ cancels. The initial water level ($\\frac{3}{7}$ of $14 = 6$ feet) confirms the sphere remains submerged after the rise. The distractor $\\frac{32}{27\\pi}$ fails to cancel $\\pi$ from numerator and denominator. The distractor $\\frac{16}{27}$ uses $r = 1$ in the sphere volume, halving the result. The distractor $\\frac{32}{9\\pi}$ omits the $\\frac{1}{3}$ factor in the sphere volume formula.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23O8PGM', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which expression is equivalent to $(3x + 11)^2 - (3x - 11)^2$?', NULL, $lyceon_json$[{"key":"A","text":"$132x$"},{"key":"B","text":"$66x$"},{"key":"C","text":"$18x^2 + 242$"},{"key":"D","text":"$242$"}]$lyceon_json$::jsonb, 'A', NULL, E'Using the difference of squares identity, $(3x + 11)^2 - (3x - 11)^2 = [(3x + 11) + (3x - 11)][(3x + 11) - (3x - 11)] = (6x)(22) = 132x$. The distractor $66x$ results from computing $(6x)(11)$ instead of $(6x)(22)$, halving the second factor. The distractor $18x^2 + 242$ comes from incorrectly adding the squared terms rather than subtracting them, yielding $2(9x^2) + 2(121)$. The distractor $242$ arises from ignoring the $x$-terms entirely and computing $2(121) = 242$, treating only the constant portions.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23QHE0M', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A factory produces $273$ widgets every $3$ hours. At the same rate, how many widgets does the factory produce in $11$ hours?', NULL, $lyceon_json$[{"key":"A","text":"$819$"},{"key":"B","text":"$1001$"},{"key":"C","text":"$903$"},{"key":"D","text":"$1093$"}]$lyceon_json$::jsonb, 'B', NULL, E'The rate is $\\frac{273}{3} = 91$ widgets per hour. In $11$ hours: $91 \\times 11 = 1001$ widgets. The value $819$ comes from incorrectly multiplying $273 \\times 3$ instead of first finding the hourly rate. The value $903$ results from a multiplication error when computing $91 \\times 11$. The value $1093$ comes from an arithmetic slip adding an extra $92$ instead of $91$ in the final step.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM243LNVQ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A university researcher randomly selects 500 adults from a national registry and surveys them about exercise habits and sleep quality. The study finds that adults who exercise at least 4 times per week report significantly better sleep quality than those who exercise fewer than 4 times per week. A journalist writes: "Exercising 4 or more times per week improves sleep quality for adults nationwide." Which of the following best identifies the flaw in the journalist''s statement?', NULL, $lyceon_json$[{"key":"A","text":"The sample size of 500 is too small to draw any conclusion."},{"key":"B","text":"The journalist claims a causal relationship, but because exercise was not randomly assigned, only an association can be concluded."},{"key":"C","text":"The study cannot be generalized to all adults because the sample was not randomly selected."},{"key":"D","text":"The study did not use a control group, so no conclusion is valid."}]$lyceon_json$::jsonb, 'B', NULL, E'The study is observational: exercise habits were not randomly assigned to participants. Although the sample was randomly selected from a national registry (supporting generalization), the lack of random assignment means only an association — not a causal relationship — can be established. The journalist''s claim that exercise "improves" sleep quality implies causation, which is the flaw. The claim that 500 is too small is not necessarily true and is not the primary issue. The claim that the study cannot be generalized is incorrect because the sample was randomly selected from a national registry. The claim that there is no control group mischaracterizes the study design; the comparison group (those exercising fewer than 4 times per week) serves as the reference group.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24Z5LEL', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'grid_in', E'The expression $\\frac{27x^3 + 125}{3x + 5}$ can be written in the form $ax^2 + bx + c$, where $a$, $b$, and $c$ are constants. What is the value of $a + b + c$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '19', ARRAY['19'], E'Recognize $27x^3 + 125 = (3x)^3 + 5^3$ as a sum of cubes, which factors as $(3x + 5)(9x^2 - 15x + 25)$. Dividing by $(3x + 5)$ yields $9x^2 - 15x + 25$. Therefore $a = 9$, $b = -15$, and $c = 25$, giving $a + b + c = 9 + (-15) + 25 = 19$. Alternatively, polynomial long division of $27x^3 + 125$ by $3x + 5$ produces the same quotient. A common error is misremembering the sum-of-cubes pattern and using $9x^2 + 15x + 25$ (sign error on the middle term), which would give $a + b + c = 49$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM261VMEJ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of 150 voters in a city found that $58\\%$ support a new park proposal. The margin of error for the survey is $4\\%$. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Exactly $58\\%$ of all voters in the city support the proposal."},{"key":"B","text":"Between $54\\%$ and $62\\%$ of the sampled voters support the proposal."},{"key":"C","text":"It is plausible that between $54\\%$ and $62\\%$ of all voters in the city support the proposal."},{"key":"D","text":"At most $62\\%$ of all voters in the city support the proposal."}]$lyceon_json$::jsonb, 'C', NULL, E'The margin of error creates a confidence interval around the sample statistic: $58\\% \\pm 4\\%$, or $54\\%$ to $62\\%$. This interval estimates the true population proportion, meaning it is plausible that between $54\\%$ and $62\\%$ of all voters support the proposal. The choice stating exactly $58\\%$ ignores sampling variability. The choice referencing the sampled voters misapplies the interval to the sample rather than the population. The choice stating at most $62\\%$ captures only the upper bound and ignores the lower bound of the interval.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26WOWI6', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'A right triangle has legs of length $11$ and $b$, and a hypotenuse of length $61$. What is the value of $b$?', NULL, $lyceon_json$[{"key":"A","text":"50"},{"key":"B","text":"55"},{"key":"C","text":"58"},{"key":"D","text":"60"}]$lyceon_json$::jsonb, 'D', NULL, E'Using the Pythagorean theorem: $11^2 + b^2 = 61^2$, so $121 + b^2 = 3721$, giving $b^2 = 3600$ and $b = 60$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28PFQYG', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'grid_in', E'In right triangle $JKL$, $\\angle K = 90°$, $JK = 7$, and $KL = 24$. What is the value of $\\sin(\\angle J)$? Express your answer as a fraction.', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '24/25', ARRAY['24/25', '0.96', '.96'], E'First find the hypotenuse $JL = \\sqrt{JK^2 + KL^2} = \\sqrt{49 + 576} = \\sqrt{625} = 25$. The sine of angle $J$ is the ratio of the side opposite angle $J$ to the hypotenuse: $\\sin(\\angle J) = \\frac{KL}{JL} = \\frac{24}{25}$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2990A03', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'What is the value of $x$ in the equation $7x - 19 = 2x + 16$?', NULL, $lyceon_json$[{"key":"A","text":"$1$"},{"key":"B","text":"$3$"},{"key":"C","text":"$7$"},{"key":"D","text":"$-7$"}]$lyceon_json$::jsonb, 'C', NULL, E'Subtracting $2x$ from both sides gives $5x - 19 = 16$. Adding $19$ to both sides gives $5x = 35$. Dividing both sides by $5$ gives $x = 7$. The value $-7$ results from a sign error when dividing. The value $3$ comes from stopping after computing $\\frac{16 - 1}{5}$ with a misread of the constant. The value $1$ results from an arithmetic slip in combining terms.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29WXUD4', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'Two independent random samples are taken from the same population of 8,500 registered voters. Sample A ($n = 250$) finds $41\\%$ support a ballot measure with a margin of error of $6\\%$. Sample B ($n = 1{,}000$) finds $44\\%$ support the measure with a margin of error of $3\\%$. Which of the following statements is best supported by these results?', NULL, $lyceon_json$[{"key":"A","text":"Sample A is more reliable because its result is closer to $50\\%$."},{"key":"B","text":"The two samples contradict each other, so neither provides useful information."},{"key":"C","text":"Sample B provides a more precise estimate of the population proportion because its margin of error is smaller."},{"key":"D","text":"The true proportion of voters who support the measure is $44\\%$ because Sample B is larger."}]$lyceon_json$::jsonb, 'C', NULL, E'Sample B has a larger sample size and a smaller margin of error ($3\\%$ vs. $6\\%$), which means it provides a more precise estimate of the population proportion. Note that the two confidence intervals overlap ($35\\%$–$47\\%$ for Sample A and $41\\%$–$47\\%$ for Sample B), so they are consistent, not contradictory. The claim that Sample A is more reliable because its result is closer to $50\\%$ confuses proximity to $50\\%$ with statistical precision. The claim that the samples contradict each other ignores the overlapping intervals. The claim that the true proportion is exactly $44\\%$ treats the sample statistic as the true value rather than an estimate.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2A0W9IF', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $g(x) = 3x^2 - 12x + 17$ can be rewritten in the form $g(x) = 3(x - h)^2 + k$. What is the minimum value of $g$?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$17$"},{"key":"C","text":"$-5$"},{"key":"D","text":"$13$"}]$lyceon_json$::jsonb, 'A', NULL, E'Complete the square: $g(x) = 3(x^2 - 4x) + 17 = 3(x^2 - 4x + 4 - 4) + 17 = 3(x - 2)^2 - 12 + 17 = 3(x - 2)^2 + 5$. Since $3(x - 2)^2 \\geq 0$ for all $x$, the minimum value of $g$ is $5$, occurring at $x = 2$. The distractor $17$ mistakes the original constant term for the minimum value without completing the square. The distractor $-5$ introduces a sign error in the final step. The distractor $13$ results from subtracting $4$ instead of $12$ (forgetting to multiply $4$ by the leading coefficient $3$ when completing the square), giving $17 - 4 = 13$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BA9PHO', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'A line passes through the points $(2, 9)$ and $(5, -3)$. Which of the following is the equation of this line in slope-intercept form?', NULL, $lyceon_json$[{"key":"A","text":"$y = -4x + 8$"},{"key":"B","text":"$y = -3x + 15$"},{"key":"C","text":"$y = -4x + 17$"},{"key":"D","text":"$y = 4x + 1$"}]$lyceon_json$::jsonb, 'C', NULL, E'The slope is $m = \\frac{-3 - 9}{5 - 2} = \\frac{-12}{3} = -4$. Using point-slope form with $(2, 9)$: $y - 9 = -4(x - 2)$, so $y = -4x + 8 + 9 = -4x + 17$. The equation $y = -4x + 8$ stops at the distributed term $-4(x - 2) = -4x + 8$ without adding the $9$. The equation $y = -3x + 15$ uses an incorrect slope from an arithmetic slip in the difference quotient. The equation $y = 4x + 1$ results from dropping the negative sign on the slope.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DPB5FM', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'grid_in', E'The quadratic function $f$ has a minimum value of $-13$ at $x = 5$, and $f(0) = 12$. What is the value of $f(8)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-4', ARRAY['-4'], E'Since $f$ has a minimum at $x = 5$, the vertex form is $f(x) = a(x - 5)^2 - 13$ for some positive constant $a$. Using $f(0) = 12$: $a(0 - 5)^2 - 13 = 12$, so $25a = 25$, giving $a = 1$. Therefore $f(x) = (x - 5)^2 - 13$. Evaluating at $x = 8$: $f(8) = (8 - 5)^2 - 13 = 9 - 13 = -4$. A common error is using $a = -1$ (confusing minimum with maximum), which would yield $f(8) = -9 - 13 = -22$. Another error is forgetting to subtract $13$, giving $f(8) = 9$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DQZ5HU', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A line of best fit for a data set is given by $y = -1.7x + 43.9$. One data point is $(11, 27)$. What is the residual for this data point?', NULL, $lyceon_json$[{"key":"A","text":"$1.8$"},{"key":"B","text":"$-1.8$"},{"key":"C","text":"$8.2$"},{"key":"D","text":"$-8.2$"}]$lyceon_json$::jsonb, 'A', NULL, E'The predicted value at $x = 11$ is $y = -1.7(11) + 43.9 = -18.7 + 43.9 = 25.2$. The residual is the actual value minus the predicted value: $27 - 25.2 = 1.8$. The value $-1.8$ results from reversing the subtraction order (predicted minus actual). The value $8.2$ comes from a calculation error in evaluating $-1.7(11)$. The value $-8.2$ combines both the subtraction reversal and the arithmetic error.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DYU656', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A rectangular garden has a length of $13$ meters and a width of $7$ meters. What is the area of the garden, in square meters?', NULL, $lyceon_json$[{"key":"A","text":"$40$"},{"key":"B","text":"$78$"},{"key":"C","text":"$91$"},{"key":"D","text":"$182$"}]$lyceon_json$::jsonb, 'C', NULL, E'The area of a rectangle is length times width: $13 \\times 7 = 91$ square meters. The distractor $40$ comes from computing the perimeter $2(13 + 7) = 40$ instead of the area. The distractor $78$ arises from an arithmetic slip such as computing $13 \\times 6$ instead of $13 \\times 7$. The distractor $182$ comes from computing $2 \\times 13 \\times 7$, doubling the area as if using a surface-area-style formula.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2E8GJ3S', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'grid_in', E'What is the value of $x$ that satisfies the equation $$\\frac{3(2x - 7)}{4} = \\frac{x + 11}{2}$$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '43/4', ARRAY['43/4', '10.75'], E'Multiplying both sides by $4$ gives $3(2x - 7) = 2(x + 11)$. Distributing yields $6x - 21 = 2x + 22$. Subtracting $2x$ from both sides gives $4x - 21 = 22$. Adding $21$ to both sides gives $4x = 43$. Dividing by $4$ gives $x = \\frac{43}{4}$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2F6REXD', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'The equation of a circle in the $xy$-plane is $x^2 + y^2 - 14x + 8y + 40 = 0$. What is the radius of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$5$"},{"key":"C","text":"$9$"},{"key":"D","text":"$25$"}]$lyceon_json$::jsonb, 'B', NULL, E'Complete the square for both variables. For $x$: $x^2 - 14x = (x - 7)^2 - 49$. For $y$: $y^2 + 8y = (y + 4)^2 - 16$. Substituting: $(x - 7)^2 - 49 + (y + 4)^2 - 16 + 40 = 0$, which simplifies to $(x - 7)^2 + (y + 4)^2 = 25$. So the radius is $r = \\sqrt{25} = 5$. The distractor $3$ arises from a sign or arithmetic error in the completing-the-square steps. The distractor $9$ comes from misidentifying $r^2$ and taking a wrong square root. The distractor $25$ confuses $r^2 = 25$ with the radius itself, failing to take the square root.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FHGKVO', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'mcq', E'A surveyor stands at point $A$ and measures the angle of elevation to the top of a building at point $B$ to be $29°$. She then walks $37$ meters directly toward the building to point $C$ and measures the angle of elevation to $B$ to be $51°$. Which of the following expressions gives the height of the building, in meters?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{37 \\sin(29°)}{\\sin(22°)}$"},{"key":"B","text":"$\\frac{37 \\sin(29°) \\cos(51°)}{\\sin(22°)}$"},{"key":"C","text":"$\\frac{37 \\tan(29°) \\tan(51°)}{\\tan(51°) - \\tan(29°)}$"},{"key":"D","text":"$\\frac{37}{\\tan(51°) - \\tan(29°)}$"}]$lyceon_json$::jsonb, 'C', NULL, E'Let $h$ be the building height. From point $A$, $\\tan(29°) = h / d_A$ where $d_A$ is the horizontal distance from $A$ to the building. From point $C$ (37 meters closer), $\\tan(51°) = h / d_C$ where $d_C = d_A - 37$. From $h = d_A \\tan(29°)$ and $h = (d_A - 37)\\tan(51°)$, solving gives $d_A = \\frac{37\\tan(51°)}{\\tan(51°) - \\tan(29°)}$, so $h = \\frac{37\\tan(29°)\\tan(51°)}{\\tan(51°) - \\tan(29°)}$. The expression $\\frac{37\\sin(29°)}{\\sin(22°)}$ omits the $\\sin(51°)$ factor needed to extract the vertical component from the oblique triangle, yielding a value that is too small. The expression $\\frac{37\\sin(29°)\\cos(51°)}{\\sin(22°)}$ incorrectly uses cosine instead of sine for the angle at the building''s base. The expression $\\frac{37}{\\tan(51°) - \\tan(29°)}$ omits the $\\tan(29°)\\tan(51°)$ product from the numerator.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FK7MJ8', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'grid_in', E'A student has at most $\\$47$ to spend on notebooks that cost $\\$3$ each and a single binder that costs $\\$11$. What is the greatest number of notebooks the student can buy?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '12', ARRAY['12'], E'The total cost must satisfy $3n + 11 \\leq 47$, where $n$ is the number of notebooks. Subtracting $11$ from both sides gives $3n \\leq 36$. Dividing both sides by $3$ gives $n \\leq 12$. Since $n$ must be a whole number, the greatest number of notebooks is $12$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2G7CWMD', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'grid_in', E'At a museum, $5$ adult tickets and $3$ child tickets cost a total of $\\$34$. At the same museum, $2$ adult tickets and $1$ child ticket cost a total of $\\$13$. What is the price, in dollars, of one adult ticket?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'Let $a$ represent the price of an adult ticket and $c$ represent the price of a child ticket. The system of equations is $5a + 3c = 34$ and $2a + c = 13$. From the second equation, $c = 13 - 2a$. Substituting into the first equation: $5a + 3(13 - 2a) = 34$, which gives $5a + 39 - 6a = 34$, so $-a = -5$ and $a = 5$. The price of one adult ticket is $\\$5$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GX5YA4', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A researcher surveys a random sample of 400 households in a county and finds that $37\\%$ have solar panels. The margin of error is $3\\%$. There are 12,000 households in the county. Based on these results, which of the following is the best estimate of the number of households in the county that have solar panels?', NULL, $lyceon_json$[{"key":"A","text":"Between 3,720 and 5,040"},{"key":"B","text":"Between 4,080 and 4,800"},{"key":"C","text":"Between 136 and 160"},{"key":"D","text":"Exactly 4,440"}]$lyceon_json$::jsonb, 'B', NULL, E'The confidence interval for the proportion is $37\\% \\pm 3\\%$, or $34\\%$ to $40\\%$. Applying this to the 12,000 households: the lower bound is $0.34 \\times 12{,}000 = 4{,}080$ and the upper bound is $0.40 \\times 12{,}000 = 4{,}800$. So between 4,080 and 4,800 households is the best estimate. The range 3,720 to 5,040 results from incorrectly computing $31\\%$ to $42\\%$ (doubling the margin of error in one direction). The range 136 to 160 applies the percentages to the sample size of 400 instead of the population. The answer of exactly 4,440 uses only the point estimate ($0.37 \\times 12{,}000$) without accounting for the margin of error.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HI1DQW', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which value of $x$ satisfies the inequality $7x - 13 \\geq 8$?', NULL, $lyceon_json$[{"key":"A","text":"$2$"},{"key":"B","text":"$3$"},{"key":"C","text":"$-3$"},{"key":"D","text":"$21$"}]$lyceon_json$::jsonb, 'B', NULL, E'Adding $13$ to both sides gives $7x \\geq 21$, and dividing both sides by $7$ gives $x \\geq 3$. The smallest integer satisfying this is $3$. The value $2$ does not satisfy the inequality because $7(2) - 13 = 1$, which is less than $8$. The value $-3$ results from incorrectly applying a sign change when isolating $x$. The value $21$ comes from failing to divide by $7$ after adding $13$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HWJJT1', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $y$-intercept of the line $5x + 4y = 20$?', NULL, $lyceon_json$[{"key":"A","text":"4"},{"key":"B","text":"5"},{"key":"C","text":"10"},{"key":"D","text":"20"}]$lyceon_json$::jsonb, 'B', NULL, E'Setting $x = 0$ in $5x + 4y = 20$ gives $4y = 20$, so $y = 5$. The $y$-intercept is $5$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IQX9ZA', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'grid_in', E'A store marks up a product by $40\\%$ over its wholesale cost, then offers a seasonal discount of $15\\%$ off the marked-up price. If the final sale price is $\\$95.20$, what was the wholesale cost, in dollars?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '80', ARRAY['80'], E'Let the wholesale cost be $w$. After a $40\\%$ markup, the price is $1.40w$. After a $15\\%$ discount on that price, the final price is $0.85 \\times 1.40w = 1.19w$. Setting $1.19w = 95.20$ gives $w = \\frac{95.20}{1.19} = 80$. A common error is to net the percentages ($40\\% - 15\\% = 25\\%$) and solve $1.25w = 95.20$, which gives the incorrect value $76.16$. Another error is applying the discount before the markup.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JZ3UQQ', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'For what value of $k$ does the system of equations below have infinitely many solutions?$$\\begin{cases} 6x - 9y = 15 \\\\ kx + 3y = -5 \\end{cases}$$', NULL, $lyceon_json$[{"key":"A","text":"$-6$"},{"key":"B","text":"$-2$"},{"key":"C","text":"$2$"},{"key":"D","text":"$6$"}]$lyceon_json$::jsonb, 'B', NULL, E'For the system to have infinitely many solutions, the two equations must be equivalent (scalar multiples of each other). Dividing the first equation by $3$ gives $2x - 3y = 5$. Multiplying the second equation by $-1$ gives $-kx - 3y = 5$. For these to be the same equation, $-k = 2$ and $-3 = -3$ (already satisfied), so $k = -2$. The value $-6$ results from incorrectly matching the original coefficient $6$ with $k$ using the wrong ratio. The value $2$ comes from dropping the negative sign when solving $-k = 2$. The value $6$ results from assuming the coefficients of $x$ must be equal without accounting for the proportionality of the entire equation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2K3RAP4', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A jar contains 5 red candies, 8 yellow candies, and 12 green candies. If one candy is selected at random, what is the probability that it is yellow?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{5}{25}$"},{"key":"B","text":"$\\frac{8}{17}$"},{"key":"C","text":"$\\frac{8}{25}$"},{"key":"D","text":"$\\frac{12}{25}$"}]$lyceon_json$::jsonb, 'C', NULL, E'The total number of candies is $5 + 8 + 12 = 25$. The probability of selecting a yellow candy is $\\frac{8}{25}$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KWGFGH', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'What is the vertex of the graph of $f(x) = 2(x - 5)^2 + 13$?', NULL, $lyceon_json$[{"key":"A","text":"$(5, 13)$"},{"key":"B","text":"$(-5, 13)$"},{"key":"C","text":"$(5, 15)$"},{"key":"D","text":"$(2, 13)$"}]$lyceon_json$::jsonb, 'A', NULL, E'For a quadratic in vertex form $f(x) = a(x - h)^2 + k$, the vertex is $(h, k)$. Here $h = 5$ and $k = 13$, so the vertex is $(5, 13)$. The distractor $(-5, 13)$ results from a sign error, reading the $(x - 5)$ term as indicating $h = -5$. The distractor $(5, 15)$ comes from incorrectly adding the leading coefficient $2$ to $13$. The distractor $(2, 13)$ misidentifies the leading coefficient as the $x$-coordinate of the vertex.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L0IXN0', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'For what value of $c$ does the equation $$3(4x - 7) - 2(cx + 5) = 8x + 1$$ have no solution?', NULL, $lyceon_json$[{"key":"A","text":"$-2$"},{"key":"B","text":"$2$"},{"key":"C","text":"$4$"},{"key":"D","text":"$10$"}]$lyceon_json$::jsonb, 'B', NULL, E'Distributing on the left side gives $12x - 21 - 2cx - 10 = 8x + 1$, which simplifies to $(12 - 2c)x - 31 = 8x + 1$. For the equation to have no solution, the coefficients of $x$ must be equal while the constants differ: $12 - 2c = 8$ and $-31 \\neq 1$. Solving $12 - 2c = 8$ gives $c = 2$, and $-31 \\neq 1$ is satisfied. The value $-2$ comes from a sign error when solving $12 - 2c = 8$. The value $4$ results from incorrectly setting up $12 - 2c = 4$. The value $10$ reflects a fundamental misunderstanding of the no-solution condition.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LPGD0B', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'grid_in', E'A chemist mixes Solution A with Solution B in a ratio of $5:3$ by volume. Solution A contains $18\\%$ acid and Solution B contains $42\\%$ acid. What percent of the mixture is acid?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '27', ARRAY['27'], E'In a $5:3$ ratio, for every $8$ parts total, $5$ parts are Solution A and $3$ parts are Solution B. The acid from Solution A is $5 \\times 0.18 = 0.90$ parts, and the acid from Solution B is $3 \\times 0.42 = 1.26$ parts. Total acid is $0.90 + 1.26 = 2.16$ parts out of $8$ total parts. The percentage is $\\frac{2.16}{8} \\times 100 = 27\\%$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2M7HM3H', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A researcher collects data on the altitude (in thousands of feet) and the boiling point of water (in $°F$) at $7$ locations. The line of best fit is $y = -1.84x + 213.6$, where $x$ is altitude in thousands of feet and $y$ is the boiling point in $°F$. The correlation coefficient is $r = -0.97$. At an altitude of $6{,}500$ feet, the actual measured boiling point is $201.5°F$. Which of the following is closest to the residual at this altitude, and what does $r = -0.97$ indicate about the model?', NULL, $lyceon_json$[{"key":"A","text":"Residual $\\approx -0.14°F$; the linear model is a strong fit for the data."},{"key":"B","text":"Residual $\\approx 0.14°F$; the linear model is a strong fit for the data."},{"key":"C","text":"Residual $\\approx -0.14°F$; the linear model is a weak fit for the data."},{"key":"D","text":"Residual $\\approx 0.14°F$; the linear model is a weak fit for the data."}]$lyceon_json$::jsonb, 'A', NULL, E'At $x = 6.5$ (thousands of feet), the predicted boiling point is $y = -1.84(6.5) + 213.6 = -11.96 + 213.6 = 201.64°F$. The residual is $201.5 - 201.64 = -0.14°F$. Since $|r| = 0.97$ is close to $1$, the linear model is a strong fit. The residual of $0.14$ with the wrong sign results from computing predicted minus actual instead of actual minus predicted. Describing $r = -0.97$ as a weak fit confuses the sign of $r$ with its magnitude; the strength of a linear relationship is measured by $|r|$, not by whether $r$ is positive or negative.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MGOW3K', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'grid_in', E'In the $xy$-plane, a circle has center $(6, -2)$ and passes through the point $(14, 4)$. A line tangent to the circle at the point $(14, 4)$ intersects the $x$-axis at the point $(a, 0)$. What is the value of $a$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '17', ARRAY['17'], E'The radius from the center $(6, -2)$ to the tangent point $(14, 4)$ has slope $\\frac{4 - (-2)}{14 - 6} = \\frac{6}{8} = \\frac{3}{4}$. The radius has length $\\sqrt{(14 - 6)^2 + (4 - (-2))^2} = \\sqrt{64 + 36} = 10$. A tangent line is perpendicular to the radius at the point of tangency, so the tangent line has slope $-\\frac{4}{3}$. Using point-slope form with point $(14, 4)$: $y - 4 = -\\frac{4}{3}(x - 14)$. Setting $y = 0$: $-4 = -\\frac{4}{3}(x - 14)$, so $4 = \\frac{4}{3}(x - 14)$, giving $x - 14 = 3$ and $x = 17$.', NULL, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MJHXV0', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'In a class of 38 students, 22 study French, 17 study Spanish, and 6 study neither language. A student is selected at random from those who study at least one language. What is the probability that the student studies both French and Spanish?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{7}{38}$"},{"key":"B","text":"$\\frac{7}{32}$"},{"key":"C","text":"$\\frac{15}{32}$"},{"key":"D","text":"$\\frac{9}{32}$"}]$lyceon_json$::jsonb, 'B', NULL, E'First find the number who study at least one language: $38 - 6 = 32$. By the inclusion-exclusion principle, the number studying both is $22 + 17 - 32 = 7$. The probability, given the student studies at least one language, is $\\frac{7}{32}$. The answer $\\frac{7}{38}$ divides by the total class size instead of conditioning on those who study at least one language. The answer $\\frac{15}{32}$ results from using $22 - 7 = 15$ (those studying only French) instead of those studying both. The answer $\\frac{9}{32}$ results from an arithmetic error in the inclusion-exclusion calculation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MN8YKT', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'The boundary line of the inequality $y < ax + b$ in the $xy$-plane has a $y$-intercept of $(0, -4)$ and passes through the point $(6, 5)$. Which of the following points is in the solution set of this inequality?', NULL, $lyceon_json$[{"key":"A","text":"$(0, 0)$"},{"key":"B","text":"$(4, 3)$"},{"key":"C","text":"$(2, -3)$"},{"key":"D","text":"$(8, 9)$"}]$lyceon_json$::jsonb, 'C', NULL, E'The boundary line passes through $(0, -4)$ and $(6, 5)$, so its slope is $\\frac{5 - (-4)}{6 - 0} = \\frac{9}{6} = \\frac{3}{2}$. The equation of the boundary line is $y = \\frac{3}{2}x - 4$. The inequality is $y < \\frac{3}{2}x - 4$, so points below this line are in the solution set. Testing $(2, -3)$: $\\frac{3}{2}(2) - 4 = -1$, and $-3 < -1$ is true, so this point satisfies the inequality. Testing $(0, 0)$: $\\frac{3}{2}(0) - 4 = -4$, and $0 < -4$ is false. Testing $(4, 3)$: $\\frac{3}{2}(4) - 4 = 2$, and $3 < 2$ is false. Testing $(8, 9)$: $\\frac{3}{2}(8) - 4 = 8$, and $9 < 8$ is false.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"graph_read_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2N9L52I', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to $7x^2 - 49x$?', NULL, $lyceon_json$[{"key":"A","text":"$7x(x - 49)$"},{"key":"B","text":"$7(x^2 - 7x)$"},{"key":"C","text":"$7x(x - 7)$"},{"key":"D","text":"$x(7x - 7)$"}]$lyceon_json$::jsonb, 'C', NULL, E'The greatest common factor of $7x^2$ and $49x$ is $7x$. Factoring gives $7x(x - 7)$. The distractor $7x(x - 49)$ results from failing to divide $49$ by $7$ when extracting the common factor. The distractor $7(x^2 - 7x)$ correctly factors out $7$ but neglects to also factor out $x$, leaving the expression only partially factored. The distractor $x(7x - 7)$ factors out only $x$ and incorrectly simplifies the remaining terms, producing $7x - 7$ instead of $7x - 49$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NI94AO', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'How many real solutions does the equation $$\\frac{3}{x - 2} + \\frac{5}{x + 1} = \\frac{4x}{x^2 - x - 2}$$ have?', NULL, $lyceon_json$[{"key":"A","text":"$0$"},{"key":"B","text":"$1$"},{"key":"C","text":"$2$"},{"key":"D","text":"$3$"}]$lyceon_json$::jsonb, 'B', NULL, E'First note that $x^2 - x - 2 = (x - 2)(x + 1)$, so $x = 2$ and $x = -1$ are excluded from the domain. Multiplying both sides by $(x - 2)(x + 1)$ gives $3(x + 1) + 5(x - 2) = 4x$, which simplifies to $3x + 3 + 5x - 10 = 4x$, then $8x - 7 = 4x$, yielding $4x = 7$ and $x = \\frac{7}{4}$. Since $\\frac{7}{4}$ is not an excluded value, there is exactly $1$ real solution. The distractor $0$ incorrectly concludes the equation has no solution, perhaps by misidentifying $\\frac{7}{4}$ as excluded. The distractor $2$ results from counting the excluded values $x = 2$ and $x = -1$ as solutions without checking validity. The distractor $3$ comes from treating the equation as degree $3$ after clearing denominators without recognizing the leading terms cancel.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NJ9R1O', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'mcq', E'In triangle $DEF$, $DE = 11$, $EF = 17$, and $\\angle DEF = 90°$. Point $G$ lies on $\\overline{DF}$ such that $\\overline{EG} \\perp \\overline{DF}$. What is the length of $\\overline{DG}$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{121}{\\sqrt{410}}$"},{"key":"B","text":"$\\frac{121}{\\sqrt{290}}$"},{"key":"C","text":"$\\frac{289}{\\sqrt{410}}$"},{"key":"D","text":"$\\frac{17}{\\sqrt{410}}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Since $\\angle DEF = 90°$, the hypotenuse is $DF = \\sqrt{DE^2 + EF^2} = \\sqrt{121 + 289} = \\sqrt{410}$. In a right triangle, the altitude from the right angle to the hypotenuse creates similar triangles. By the geometric mean relation, $DG = \\frac{DE^2}{DF} = \\frac{121}{\\sqrt{410}}$. The distractor $\\frac{121}{\\sqrt{290}}$ incorrectly computes $17^2$ as $169$ instead of $289$, giving $\\sqrt{121 + 169} = \\sqrt{290}$. The distractor $\\frac{289}{\\sqrt{410}}$ uses $EF^2$ instead of $DE^2$ in the numerator, which gives the projection $FG$ rather than $DG$. The distractor $\\frac{17}{\\sqrt{410}}$ divides $EF$ by $DF$ instead of squaring $DE$ and dividing by $DF$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NOA67N', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a radius of $11$ centimeters. What is the circumference of the circle, in centimeters?', NULL, $lyceon_json$[{"key":"A","text":"$11\\pi$"},{"key":"B","text":"$22\\pi$"},{"key":"C","text":"$44\\pi$"},{"key":"D","text":"$121\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'The circumference of a circle is $C = 2\\pi r = 2\\pi(11) = 22\\pi$ centimeters. The distractor $11\\pi$ uses only $\\pi r$ instead of $2\\pi r$, omitting the factor of $2$. The distractor $44\\pi$ incorrectly doubles the correct circumference, as if computing $4\\pi r$. The distractor $121\\pi$ computes $\\pi r^2 = \\pi(11)^2 = 121\\pi$, which is the area formula, not the circumference.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PFWTQ4', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'grid_in', E'A cone has a radius of $3$ inches and a height of $11$ inches. What is the volume of the cone, in cubic inches? (Use $\\pi \\approx 3.14$ and round to the nearest whole number.)', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '104', ARRAY['104'], E'The volume of a cone is $V = \\frac{1}{3}\\pi r^2 h = \\frac{1}{3}(3.14)(3^2)(11) = \\frac{1}{3}(3.14)(9)(11) = \\frac{1}{3}(310.86) = 103.62$, which rounds to $104$ cubic inches.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Q8WUB7', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A jacket originally priced at $\\$74$ is on sale for $\\$55.50$. What is the percent discount, to the nearest whole percent?', NULL, $lyceon_json$[{"key":"A","text":"$18\\%$"},{"key":"B","text":"$25\\%$"},{"key":"C","text":"$33\\%$"},{"key":"D","text":"$22\\%$"}]$lyceon_json$::jsonb, 'B', NULL, E'The discount amount is $74 - 55.50 = 18.50$. The percent discount is $\\frac{18.50}{74} \\times 100 = 25\\%$. The value $18\\%$ comes from rounding the discount amount itself as though it were the percentage. The value $33\\%$ results from dividing the discount by the sale price ($\\frac{18.50}{55.50}$) instead of the original price. The value $22\\%$ comes from a computational error in the division.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RLYMNM', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'Researchers want to determine whether a new fertilizer increases crop yield. They randomly assign 60 plots of farmland to receive either the new fertilizer or a standard fertilizer, with 30 plots in each group. After the growing season, the plots with the new fertilizer had an average yield $17\\%$ higher than those with the standard fertilizer. Which of the following conclusions is best supported?', NULL, $lyceon_json$[{"key":"A","text":"The new fertilizer is associated with higher crop yield, but a causal relationship has not been established."},{"key":"B","text":"The new fertilizer causes higher crop yield, and the result applies to all farmland everywhere."},{"key":"C","text":"No conclusion can be drawn because the sample size is too small."},{"key":"D","text":"The new fertilizer causes higher crop yield for these plots, but the result cannot necessarily be generalized to all farmland."}]$lyceon_json$::jsonb, 'D', NULL, E'Because the study uses random assignment to treatment groups, a causal conclusion is justified: the new fertilizer causes higher crop yield for the plots studied. However, the plots were not described as randomly selected from a larger population of all farmland, so the result cannot necessarily be generalized beyond these 60 plots. The choice stating only an association ignores that random assignment supports causal inference. The choice claiming the result applies to all farmland everywhere goes beyond what a non-randomly-sampled experiment supports. The choice claiming no conclusion can be drawn due to sample size is incorrect; 60 plots with random assignment is a valid experimental design.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2T9HBAG', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'Two parallel lines are cut by a transversal. One of the corresponding angles measures $118°$. What is the measure, in degrees, of its co-interior (same-side interior) angle on the same transversal?', NULL, $lyceon_json$[{"key":"A","text":"$118°$"},{"key":"B","text":"$72°$"},{"key":"C","text":"$62°$"},{"key":"D","text":"$28°$"}]$lyceon_json$::jsonb, 'C', NULL, E'When parallel lines are cut by a transversal, corresponding angles are equal, so the angle on the same side is $118°$. Co-interior angles are supplementary: $180° - 118° = 62°$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TALBJB', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'grid_in', E'The linear function $g(x) = mx + 19$ passes through the point $(7, -16)$. What is the value of $g(3)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4', ARRAY['4'], E'Since $g(7) = -16$, substituting gives $7m + 19 = -16$. Solving: $7m = -35$, so $m = -5$. The function is $g(x) = -5x + 19$. Evaluating at $x = 3$: $g(3) = -5(3) + 19 = -15 + 19 = 4$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TKNAHZ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'grid_in', E'The ordered data set $4, 11, 14, 19, 23, 26, 33$ has a new value of $61$ added to it. What is the positive difference between the interquartile range of the new $8$-value data set and the interquartile range of the original $7$-value data set?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '2', ARRAY['2'], E'For the original $7$ values ($4, 11, 14, 19, 23, 26, 33$), the median is the $4$th value, $19$. The lower half is $\\{4, 11, 14\\}$, so $Q_1 = 11$. The upper half is $\\{23, 26, 33\\}$, so $Q_3 = 26$. The original IQR is $26 - 11 = 15$. After adding $61$, the new data set is $4, 11, 14, 19, 23, 26, 33, 61$ ($8$ values). The lower half is $\\{4, 11, 14, 19\\}$, so $Q_1 = \\frac{11 + 14}{2} = 12.5$. The upper half is $\\{23, 26, 33, 61\\}$, so $Q_3 = \\frac{26 + 33}{2} = 29.5$. The new IQR is $29.5 - 12.5 = 17$. The positive difference is $17 - 15 = 2$. A common error is computing the range ($61 - 4 = 57$) instead of the interquartile range, or failing to recalculate the quartiles when the data set size changes from odd to even.', NULL, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ULXWWS', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'grid_in', E'A line perpendicular to $5x - 2y = 8$ passes through the point $(1, 11)$. What is the $y$-intercept of this line? (Enter only the $y$-coordinate.)', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '57/5', ARRAY['57/5', '11.4'], E'Rewriting $5x - 2y = 8$ in slope-intercept form gives $y = \\frac{5}{2}x - 4$, so the slope is $\\frac{5}{2}$. A perpendicular line has slope $-\\frac{2}{5}$. Using point-slope form with $(1, 11)$: $y - 11 = -\\frac{2}{5}(x - 1)$, which gives $y = -\\frac{2}{5}x + \\frac{2}{5} + 11 = -\\frac{2}{5}x + \\frac{57}{5}$. The $y$-intercept is $\\frac{57}{5}$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VTC49B', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'A data set contains the values $3, 7, 7, 9, 11, 11, 11, 13, 17$. What is the mode of this data set?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$9$"},{"key":"C","text":"$11$"},{"key":"D","text":"$13$"}]$lyceon_json$::jsonb, 'C', NULL, E'The mode is the value that appears most frequently. The value $11$ appears $3$ times, which is more than any other value. The value $7$ appears only $2$ times, so it is not the mode. The value $9$ is the median (middle value), not the mode. The value $13$ appears only once and may be confused with a nearby frequently occurring value.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2W43LZW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'The ages of $6$ participants in a workshop are $19, 23, 27, 31, 35, 41$. If the oldest participant ($41$) is replaced by a new participant aged $29$, which of the following correctly describes the change in the mean and median?', NULL, $lyceon_json$[{"key":"A","text":"Both the mean and the median decrease."},{"key":"B","text":"The mean decreases and the median stays the same."},{"key":"C","text":"The mean stays the same and the median decreases."},{"key":"D","text":"The mean decreases and the median increases."}]$lyceon_json$::jsonb, 'A', NULL, E'Original set: $19, 23, 27, 31, 35, 41$. Mean $= \\frac{176}{6} \\approx 29.33$. Median $= \\frac{27 + 31}{2} = 29$. New set: $19, 23, 27, 29, 31, 35$. Mean $= \\frac{164}{6} \\approx 27.33$. Median $= \\frac{27 + 29}{2} = 28$. Both the mean and the median decrease. The claim that the median stays the same is incorrect because replacing $41$ with $29$ shifts $29$ into the ordered list between the two middle values, changing the median from $29$ to $28$. The claim that the mean stays the same ignores that the sum decreased by $12$. The claim that the median increases contradicts the computed new median of $28 < 29$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2W8A6EI', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A scatterplot shows a strong negative linear association between the number of hours a student spends on social media per day and their score on a reading comprehension test. Which of the following best describes this association?', NULL, $lyceon_json$[{"key":"A","text":"As social media hours increase, test scores tend to increase."},{"key":"B","text":"As social media hours increase, test scores tend to decrease."},{"key":"C","text":"There is no consistent relationship between social media hours and test scores."},{"key":"D","text":"Students who spend more time on social media always score lower on the test."}]$lyceon_json$::jsonb, 'B', NULL, E'A strong negative linear association means that as one variable increases, the other tends to decrease. Therefore, as social media hours increase, test scores tend to decrease. The claim that test scores tend to increase describes a positive association, not a negative one. The claim that there is no consistent relationship contradicts the given information of a strong association. The claim that students always score lower overstates the association; a trend describes what tends to happen, not what always happens.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WGHYP0', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A plumber charges a flat fee of $\\$47$ plus $\\$29$ per hour for each service call. The total cost, in dollars, for a service call lasting $h$ hours is given by $C(h) = 29h + 47$. What does the value $29$ represent in this function?', NULL, $lyceon_json$[{"key":"A","text":"The total cost of a one-hour service call"},{"key":"B","text":"The rate of change in cost per additional hour worked"},{"key":"C","text":"The fixed cost before any hours are worked"},{"key":"D","text":"The minimum number of hours for a service call"}]$lyceon_json$::jsonb, 'B', NULL, E'In the function $C(h) = 29h + 47$, the coefficient $29$ multiplies the variable $h$, making it the slope of the linear function. The slope represents the rate of change — the cost increases by $\\$29$ for each additional hour worked. The total cost of a one-hour call would be $C(1) = 29 + 47 = 76$, not $29$ alone. The fixed cost before any hours are worked is the constant term $47$, not $29$. Nothing in the function defines a minimum number of hours.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WZ959D', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'The equation $x^2 - 8x + k = 0$ has exactly one real solution. What is the value of $k$?', NULL, $lyceon_json$[{"key":"A","text":"$8$"},{"key":"B","text":"$16$"},{"key":"C","text":"$-16$"},{"key":"D","text":"$64$"}]$lyceon_json$::jsonb, 'B', NULL, E'A quadratic equation has exactly one real solution when its discriminant equals zero. For $x^2 - 8x + k = 0$, the discriminant is $(-8)^2 - 4(1)(k) = 64 - 4k$. Setting $64 - 4k = 0$ gives $k = 16$. The distractor $8$ arises from using $\\frac{b}{a} = \\frac{8}{1}$ instead of $\\frac{b^2}{4a}$, confusing the discriminant formula. The distractor $-16$ introduces a sign error in solving $64 - 4k = 0$. The distractor $64$ results from setting $k = b^2$ without dividing by $4a$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XLF1JK', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A recipe calls for $\\frac{7}{4}$ cups of rice to make $14$ servings. How many cups of rice are needed to make $8$ servings?', NULL, $lyceon_json$[{"key":"A","text":"$1$"},{"key":"B","text":"$\\frac{3}{4}$"},{"key":"C","text":"$2$"},{"key":"D","text":"$\\frac{7}{8}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The rate is $\\frac{7/4}{14} = \\frac{7}{56} = \\frac{1}{8}$ cups per serving. For $8$ servings: $8 \\times \\frac{1}{8} = 1$ cup. The answer $\\frac{3}{4}$ results from an arithmetic error in the unit rate calculation. The answer $2$ comes from incorrectly doubling the unit rate. The answer $\\frac{7}{8}$ results from dividing $\\frac{7}{4}$ by $2$ instead of computing the correct proportion.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XZ6IJT', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'grid_in', E'What is the positive solution of $x^2 - 5x - 36 = 0$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '9', ARRAY['9'], E'Factor the quadratic: $x^2 - 5x - 36 = (x - 9)(x + 4) = 0$, giving $x = 9$ or $x = -4$. The positive solution is $9$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZGGUMC', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A health researcher finds that people who drink herbal tea daily have lower blood pressure on average than those who do not. The study was observational. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"Drinking herbal tea causes lower blood pressure."},{"key":"B","text":"There is an association between drinking herbal tea daily and lower blood pressure."},{"key":"C","text":"People with low blood pressure prefer herbal tea."},{"key":"D","text":"Herbal tea has no effect on blood pressure."}]$lyceon_json$::jsonb, 'B', NULL, E'Because the study is observational (not a randomized experiment), no causal conclusion can be drawn. The most appropriate conclusion is that there is an association between daily herbal tea consumption and lower blood pressure. The claim that herbal tea causes lower blood pressure incorrectly infers causation from an observational study. The claim that people with low blood pressure prefer herbal tea reverses the direction of the observed relationship without justification. The claim that herbal tea has no effect contradicts the observed association in the data.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20M2TYN', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is writing a research summary about archaeological dating methods and wants to emphasize a limitation of radiocarbon dating that makes dendrochronology a valuable complementary technique. Which choice most effectively accomplishes this goal?
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20TRO7K', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the second sentence in the text?', E'For decades, marine biologists assumed that the giant Pacific octopus was a strictly solitary hunter. However, footage captured by remotely operated vehicles near the Aleutian Trench in 2021 revealed clusters of up to nine individuals foraging cooperatively around hydrothermal vent fields, coordinating their movements to flush prey from crevices in the basalt.', $lyceon_json$[{"key":"A","text":"It presents evidence that contradicts a previously held scientific assumption."},{"key":"B","text":"It proposes a hypothesis to explain an unusual animal behavior."},{"key":"C","text":"It describes the methodology used in a marine biology experiment."},{"key":"D","text":"It summarizes the longstanding consensus about octopus behavior."}]$lyceon_json$::jsonb, 'A', NULL, E'The first sentence establishes the longstanding assumption that the giant Pacific octopus hunts alone. The second sentence, introduced by "However," presents concrete video evidence of cooperative foraging, directly contradicting that assumption. The second sentence does not propose a hypothesis; it reports observed behavior without offering a causal explanation. It also does not describe experimental methodology — it identifies the recording technology only to contextualize the evidence. Summarizing the longstanding consensus is the function of the first sentence, not the second.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21EU89W', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'A team of agricultural scientists at the University of Ghana hypothesizes that intercropping cassava with pigeon pea reduces soil nitrogen depletion because pigeon pea, a legume, fixes atmospheric nitrogen through symbiotic root nodules. If this hypothesis is correct, fields where cassava is intercropped with pigeon pea should show measurably higher soil nitrogen levels after one growing season compared to fields planted with cassava alone.', $lyceon_json$[{"key":"A","text":"Cassava-pigeon pea intercropped plots had 34% higher soil nitrogen than cassava monoculture plots after seven months."},{"key":"B","text":"Pigeon pea yields were lower in intercropped fields than in pigeon pea monoculture fields."},{"key":"C","text":"Cassava plants in intercropped fields grew 12% taller than cassava in monoculture fields."},{"key":"D","text":"Farmers in the study region prefer intercropping because it reduces labor costs during harvest."}]$lyceon_json$::jsonb, 'A', NULL, E'The hypothesis specifically predicts that intercropping with pigeon pea will result in higher soil nitrogen compared to cassava alone. The finding that intercropped plots had 34% higher soil nitrogen directly confirms this prediction. The observation about lower pigeon pea yields in intercropped fields addresses yield rather than soil nitrogen, so it does not bear on the nitrogen-fixation hypothesis. Taller cassava plants might be a downstream effect of better nutrition, but plant height does not directly measure soil nitrogen levels, making it only indirectly relevant. Farmers'' preference based on labor costs is entirely unrelated to the biological mechanism the hypothesis proposes.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22BD8P5', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which quotation from a literary scholar, if accurately cited, would best support the claim presented in the text?', E'Some literary historians argue that Nella Larsen''s 1929 novel Passing is less concerned with racial identity than it is with the constraints imposed on women''s autonomy in the early twentieth century. According to these scholars, the protagonist Irene Redfield''s anxieties about Clare Kendry stem not from Clare''s decision to pass as white but from Irene''s fear that Clare''s transgressive freedom threatens the carefully regulated domestic life Irene has built for herself.', $lyceon_json$[{"key":"A","text":"\"Larsen structures the novel's tension around Irene's need to police the boundaries of her domestic sphere, which Clare's very existence destabilizes regardless of race.\""},{"key":"B","text":"\"Passing remains the definitive literary exploration of the color line in Harlem Renaissance fiction.\""},{"key":"C","text":"\"Larsen drew heavily on her own experience of racial ambiguity in Copenhagen to craft the character of Clare Kendry.\""},{"key":"D","text":"\"The novel's final scene is deliberately ambiguous, leaving readers uncertain whether Clare's death was accidental or intentional.\""}]$lyceon_json$::jsonb, 'A', NULL, E'The passage claims that the novel''s core concern is women''s autonomy rather than racial identity, with Irene fearing Clare''s threat to her regulated domestic life. The quotation about Irene policing her domestic sphere, which Clare destabilizes regardless of race, directly echoes and supports this reading. The quotation calling Passing the definitive exploration of the color line supports the opposite interpretation—that the novel is fundamentally about race. The statement about Larsen''s personal background in Copenhagen addresses biographical context and authorial inspiration, not the thematic claim about women''s autonomy. The observation about the final scene''s ambiguity concerns narrative technique rather than the specific argument about autonomy versus racial identity.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23TMNKE', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'During the late nineteenth century, Brazilian abolitionists organized clandestine networks—known as caifazes—to transport enslaved people from plantations in São Paulo province to quilombo settlements or across provincial borders to regions where enforcement of fugitive-recapture laws was weaker. Plantation owners responded by hiring private militias to patrol roads and river crossings, yet the caifazes continued to operate effectively. Historians attribute the networks'' resilience in part to the complicity of urban free Black communities and sympathetic postal workers who relayed coded messages through the imperial mail system. This evidence implies that the success of the caifazes depended not solely on secrecy but also on ________', $lyceon_json$[{"key":"A","text":"the willingness of participants embedded in legitimate social institutions to subvert those institutions' normal functions."},{"key":"B","text":"the financial support of wealthy European abolitionists who funded operations in São Paulo."},{"key":"C","text":"the inability of the Brazilian imperial government to maintain a professional police force in rural areas."},{"key":"D","text":"the geographic isolation of quilombo settlements, which made them difficult for plantation militias to locate."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage attributes the networks'' resilience to the complicity of urban free Black communities and sympathetic postal workers who used the imperial mail system to relay coded messages. This points to people within legitimate institutions—the postal system and urban civic life—subverting those institutions to support the caifazes. The inference that European abolitionists funded the operations introduces information not found in or supported by the passage. The claim about the government''s inability to maintain a rural police force is not discussed; the passage mentions private militias, not government policing failures. Geographic isolation of quilombos may have played a role, but the passage specifically highlights institutional complicity, not geographic factors, as the key to the networks'' continued effectiveness.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26W3Q4F', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'Architect Sonia Velarde''s 2023 monograph on adaptive reuse argues that converting decommissioned grain elevators into residential lofts preserves a city''s industrial heritage while addressing housing scarcity. She cites the transformation of a 1937 concrete elevator complex in Duluth, Minnesota, into 82 affordable apartments as a model project. Yet Velarde acknowledges that such conversions can inadvertently accelerate gentrification in surrounding neighborhoods, displacing the very working-class communities whose labor built the original structures.', $lyceon_json$[{"key":"A","text":"It introduces a claim, provides a supporting example, and then presents a complication that qualifies the claim."},{"key":"B","text":"It contrasts two competing theories about urban development and endorses one over the other."},{"key":"C","text":"It describes a historical event, analyzes its causes, and predicts its long-term consequences."},{"key":"D","text":"It poses a research question, summarizes experimental findings, and identifies areas for future study."}]$lyceon_json$::jsonb, 'A', NULL, E'The text first presents Velarde''s argument that converting grain elevators preserves heritage and addresses housing needs (a claim). It then offers the Duluth elevator complex as a concrete supporting example. Finally, it introduces the complication that such conversions can trigger gentrification, qualifying the initial positive claim. The text does not contrast two competing theories — it presents one architect''s argument and then her own acknowledgment of its limitation. It does not describe a historical event''s causes or predict consequences; the Duluth project is used illustratively rather than analyzed historically. No research question is posed, no experimental findings are summarized, and no future study areas are identified.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW291VF43', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing an essay about urban beekeeping and wants to present both a benefit and a concern to give readers a balanced perspective. Which choice most effectively accomplishes this goal?
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2AJIM9P', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The Galápagos marine iguana is the only lizard species known to forage in the ocean. It dives beneath the surface to graze on algae growing on submerged _______ it can remain underwater for nearly forty minutes at a time.', $lyceon_json$[{"key":"A","text":"rocks, and"},{"key":"B","text":"rocks"},{"key":"C","text":"rocks,"},{"key":"D","text":"rocks and,"}]$lyceon_json$::jsonb, 'A', NULL, E'The blank sits between two independent clauses: one describing the iguana''s diving behavior and one describing how long it can stay underwater. The choice "rocks, and" correctly joins the two independent clauses with a comma followed by the coordinating conjunction "and." The choice "rocks" creates a run-on sentence by fusing two independent clauses with no punctuation or conjunction. The choice "rocks," produces a comma splice, joining two independent clauses with only a comma and no conjunction. The choice "rocks and," misplaces the comma after the conjunction rather than before it, violating standard comma-conjunction order.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2AT0UO5', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Neuroscientists studying memory consolidation have found that sleep plays a critical role in transferring information from short-term to long-term storage. Participants in a 2023 study who napped for 47 minutes after learning a sequence of abstract symbols recalled 31 percent more symbols the following day than those who stayed awake. ______ a separate research team observed that subjects who were prevented from entering deep sleep — even when total sleep duration was held constant — showed no significant improvement in recall, suggesting that the specific architecture of sleep, not merely its duration, drives the consolidation effect.', $lyceon_json$[{"key":"A","text":"Similarly,"},{"key":"B","text":"Furthermore,"},{"key":"C","text":"Accordingly,"},{"key":"D","text":"Specifically,"}]$lyceon_json$::jsonb, 'B', NULL, E'The third sentence introduces an additional piece of evidence from a separate research team that extends the argument by adding a new dimension — sleep architecture, not just sleep itself, matters for consolidation. "Furthermore," correctly signals that this is supplementary evidence building on the previous finding. "Similarly," suggests the new finding merely parallels the prior one, but the third sentence does more than repeat a comparable result: it introduces a distinct and deeper insight about the mechanism (sleep architecture vs. duration). "Accordingly," implies the third sentence is a logical consequence of the napping study, but the separate team''s finding is independent evidence, not a conclusion drawn from the prior result. "Specifically," would indicate a narrowing or clarification of the immediately preceding point, but the third sentence reports an entirely separate experiment with its own subjects and methodology rather than elaborating on the napping study''s details.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2B7J90F', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the text?', E'In 1947, the mathematician Stanisław Ulam, recovering from viral encephalitis, passed the time by playing solitaire and wondering about the probability of winning a given hand. Rather than attempting a combinatorial proof, Ulam proposed running the game thousands of times on an electronic computer and tallying the outcomes. His colleague John von Neumann recognized the broader potential of this approach and helped develop it into a general computational technique, eventually code-named ''Monte Carlo'' after the famous casino. Today, Monte Carlo simulations underpin applications ranging from nuclear-physics modeling to financial-risk assessment, yet the method''s origin was decidedly informal: a convalescing mathematician idly shuffling cards.', $lyceon_json$[{"key":"A","text":"The Monte Carlo method arose from a casual observation about card-game probabilities and grew into a widely applied computational technique."},{"key":"B","text":"John von Neumann was primarily responsible for inventing the Monte Carlo simulation method during the 1940s."},{"key":"C","text":"Monte Carlo simulations are most effective when applied to problems in nuclear physics and financial modeling."},{"key":"D","text":"Stanisław Ulam's illness prevented him from producing a formal combinatorial proof of solitaire probabilities."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage traces how the Monte Carlo method originated from Ulam''s informal curiosity about solitaire probabilities during his convalescence and then expanded, through von Neumann''s involvement, into a general-purpose computational technique with diverse modern applications. The option crediting von Neumann as the primary inventor misrepresents the passage, which attributes the initial idea to Ulam and describes von Neumann as a collaborator who recognized its broader potential. The claim that Monte Carlo simulations are most effective for nuclear physics and finance overstates what the passage says; those fields are cited as examples, not as domains of peak effectiveness. The option about Ulam''s illness preventing a formal proof captures only a minor detail and misses the broader narrative about the method''s development and impact.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BN7OHK', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'During the late nineteenth century, industrial dye manufacturers in Germany dominated global markets by synthesizing vibrant pigments from coal tar derivatives, drastically undercutting the price of plant-based dyes. Indigo growers in Bengal, who had supplied European textile mills for generations, saw demand for their crop collapse within a single decade. ______ the synthetic dyes that replaced natural indigo degraded more rapidly under ultraviolet exposure, a shortcoming that contemporary textile conservators now struggle with when preserving garments from that era.', $lyceon_json$[{"key":"A","text":"In addition,"},{"key":"B","text":"Ironically,"},{"key":"C","text":"Therefore,"},{"key":"D","text":"Previously,"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage establishes that synthetic dyes triumphed over natural indigo by being cheaper, yet the third sentence reveals an unexpected disadvantage of the synthetics — they degrade faster under UV exposure. This is a paradoxical reversal: the product that won on cost carried a hidden flaw that now creates problems for conservators. "Ironically," correctly signals this surprising contradiction between the commercial success of synthetic dyes and their unforeseen inferiority in durability. "In addition," treats the third sentence as simply more information on the same topic, but it fails to capture the crucial element of surprise and reversal inherent in a supposed improvement turning out to be worse in an important respect. "Therefore," implies the degradation is a logical consequence of the market dominance, but faster UV degradation is a material property unrelated to market success — it is an unexpected twist, not a predictable result. "Previously," incorrectly signals a shift backward in time, but the third sentence does not describe events that preceded the synthetic dye revolution; it describes a lasting consequence discovered later.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CAPZOS', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the underlined portion within the text as a whole?', E'Ethnomusicologist Kwan Ji-Yeon has catalogued over 340 distinct tuning systems used in sub-Saharan African lamellophone traditions, a figure that dwarfs the twelve-tone equal temperament standard in Western classical music. Her taxonomy reveals that many of these tuning systems encode cosmological and kinship information: among the Shona of Zimbabwe, for instance, the intervallic structure of mbira dzavadzimu tunings mirrors the hierarchical relationships within the ancestral spirit world. __This finding complicates the widespread musicological assumption that tuning systems arise primarily from acoustic or psychophysical constraints__, suggesting instead that cultural epistemology can be a dominant generative force in pitch organization.', $lyceon_json$[{"key":"A","text":"It identifies a prevailing scholarly view that the preceding evidence calls into question."},{"key":"B","text":"It reiterates the central finding of Kwan's research to emphasize its significance."},{"key":"C","text":"It introduces a new line of evidence that supports the claim made in the first sentence."},{"key":"D","text":"It concedes a limitation of Kwan's methodology before presenting a counterargument."}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined portion names a specific scholarly assumption — that tuning systems arise primarily from acoustic or psychophysical constraints — and states that the preceding evidence (tunings encoding cosmological and kinship information) complicates that assumption. Its function is to identify a prevailing view that the evidence challenges. The underlined portion does not reiterate Kwan''s central finding; instead, it names an external assumption that the finding disrupts. It does not introduce new evidence — the Shona mbira example was presented in the preceding sentence — but rather articulates the theoretical implication of that evidence. No methodological limitation is conceded; the text presents the finding as robust and uses it to challenge an existing assumption rather than acknowledging weaknesses in how it was obtained.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CMSD3Z', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the main idea of the text?', E'Conventional paleontological wisdom held that the mass extinction at the end of the Permian period, roughly 252 million years ago, obliterated marine diversity so thoroughly that ecological recovery required 10 million years. However, a 2023 analysis of fossil beds in Guizhou Province, China, led by paleobiologist Xu Dai, revealed that complex marine ecosystems—including apex predators, reef-builders, and nektonic filter feeders—had re-established themselves within just 1 million years of the extinction boundary. Xu''s team argues that recovery speed depended less on the severity of the extinction itself and more on the rate at which ocean chemistry—particularly dissolved-oxygen levels and carbonate saturation—returned to hospitable conditions. Where geochemical recovery was rapid, biological diversification followed almost immediately, suggesting that the traditional 10-million-year timeline may reflect sluggish geochemical normalization in the regions previously studied rather than any intrinsic biological constraint.', $lyceon_json$[{"key":"A","text":"The Permian mass extinction was less severe than paleontologists originally believed it to be."},{"key":"B","text":"Recent fossil evidence suggests post-extinction marine recovery was governed by geochemical conditions rather than by a fixed biological timeline."},{"key":"C","text":"Xu Dai's research team discovered previously unknown species of apex predators in Guizhou Province fossil beds."},{"key":"D","text":"Dissolved-oxygen levels and carbonate saturation are the two most important factors in sustaining modern marine ecosystems."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage contrasts the traditional view of a 10-million-year recovery with new evidence showing recovery within 1 million years, and it attributes the difference to the rate of geochemical normalization rather than any fixed biological constraint. The option about geochemical conditions governing recovery captures this central argument. The claim that the Permian extinction was less severe than believed distorts the passage, which does not question the extinction''s severity but rather reinterprets the recovery timeline. The suggestion that Xu''s team discovered unknown apex predator species misreads the passage: it states that complex ecosystems including apex predators had re-established, not that new species were discovered. The option about dissolved oxygen and carbonate saturation being the most important factors for modern marine ecosystems extrapolates beyond the passage, which discusses post-Permian recovery, not present-day ocean ecology.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CSGT6G', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding from the study, if accurate, would most directly undermine the researchers'' conclusion?', E'Economists at the Stockholm School of Economics analyzed employment data from 14 European Union member states between 2011 and 2022 and concluded that increases in national minimum-wage floors led to net employment growth in low-skill sectors. The researchers attributed this counterintuitive result to a demand-side stimulus: higher wages in these sectors increased workers'' disposable income, which they spent disproportionately at local businesses that themselves employed low-skill workers, creating a self-reinforcing cycle of demand and hiring.', $lyceon_json$[{"key":"A","text":"In 9 of the 14 countries studied, minimum-wage increases coincided with expansions of government-subsidized employment programs that hired low-skill workers."},{"key":"B","text":"Workers in low-skill sectors tended to save a larger share of their income than the national average."},{"key":"C","text":"Countries that did not raise their minimum wages experienced modest employment declines in low-skill sectors during the same period."},{"key":"D","text":"Inflation-adjusted wages in high-skill sectors grew at a faster rate than wages in low-skill sectors across all 14 countries."}]$lyceon_json$::jsonb, 'A', NULL, E'The researchers conclude that minimum-wage increases caused employment growth through a demand-side spending cycle. The finding that 9 of the 14 countries simultaneously expanded government-subsidized employment programs introduces a confounding variable that could explain the observed hiring growth independently of the wage increase, directly undermining the causal claim. The finding about higher saving rates among low-skill workers would weaken the demand-stimulus mechanism but only partially, since it does not offer an alternative explanation for the employment growth itself. The observation that countries without wage increases saw employment declines actually supports the researchers'' conclusion by suggesting a correlation between wage policy and employment outcomes. Faster wage growth in high-skill sectors is irrelevant to the causal mechanism the researchers propose, which concerns spending patterns among low-skill workers specifically.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DCA3SG', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Neuroscientists have long observed that patients with damage to the ventromedial prefrontal cortex (vmPFC) perform normally on standard intelligence tests and logical-reasoning tasks yet make catastrophically poor real-life decisions, particularly in situations involving personal risk and social consequence. A 2024 study by Yashoda Mehta and colleagues used functional MRI to show that in neurotypical adults, the vmPFC activates strongly when subjects evaluate hypothetical scenarios with uncertain outcomes but not when they solve deterministic logic puzzles. The researchers further found that vmPFC activation correlates with the integration of affective signals—gut feelings and emotional valence—into the decision process. Taken together, these findings suggest that ________', $lyceon_json$[{"key":"A","text":"effective real-world decision-making requires incorporating emotional information in a way that purely logical reasoning does not capture."},{"key":"B","text":"patients with vmPFC damage are unable to experience emotions in any context."},{"key":"C","text":"functional MRI is a more reliable measure of cognitive ability than standard intelligence tests."},{"key":"D","text":"deterministic logic puzzles engage a wider range of brain regions than uncertain-outcome scenarios do."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes that vmPFC-damaged patients reason logically but decide poorly in real life, and that the vmPFC integrates emotional signals during uncertain decisions but not during deterministic puzzles. The logical conclusion is that real-world decision-making depends on emotional integration that pure logical reasoning does not supply. The claim that vmPFC-damaged patients cannot experience emotions at all goes far beyond the passage, which says they make poor decisions, not that they lack all emotional experience. The suggestion that fMRI is more reliable than intelligence tests conflates the study''s tool with a claim about comparative validity the passage never makes. The assertion that logic puzzles engage more brain regions than uncertain scenarios reverses the passage''s implication: the vmPFC activates for uncertain scenarios but not for deterministic puzzles, suggesting the opposite pattern of neural engagement.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ETGAZS', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'By the time the conservation team arrived at the wetland reserve in March 2019, the invasive reed Phragmites australis _______ nearly seventy percent of the native sedge meadow, displacing several bird species that depended on the original habitat.', $lyceon_json$[{"key":"A","text":"was overtaking"},{"key":"B","text":"had overtaken"},{"key":"C","text":"has overtaken"},{"key":"D","text":"overtakes"}]$lyceon_json$::jsonb, 'B', NULL, E'The sentence describes an action (the reed overtaking the meadow) that was completed before another past event (the team''s arrival in March 2019). The construction "By the time... arrived" signals that the past perfect tense is required to indicate the earlier of two past actions, making "had overtaken" correct. The choice "was overtaking" uses the past progressive, which would indicate the action was ongoing at the time of arrival rather than already completed, conflicting with the "nearly seventy percent" phrasing that implies a completed extent. The choice "has overtaken" uses the present perfect, which connects a past action to the present and is inconsistent with the past-tense frame established by "arrived" and the specific past date. The choice "overtakes" uses the simple present tense, which is incompatible with the past time frame of the entire passage.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EW11H8', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the text, what does the word "channeled" most nearly mean?', E'In a 2019 study of urban beekeeping cooperatives, researchers found that participants channeled their enthusiasm for environmental activism into tangible neighborhood projects, establishing rooftop apiaries and pollinator gardens across seventeen city blocks in Portland, Oregon.', $lyceon_json$[{"key":"A","text":"directed"},{"key":"B","text":"excavated"},{"key":"C","text":"broadcast"},{"key":"D","text":"restrained"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes participants taking their enthusiasm and focusing it into specific projects. "Directed" captures this sense of guiding energy toward a particular end. "Excavated" refers to digging or unearthing physical material, which is incoherent in this context about enthusiasm. "Broadcast" means to spread widely or transmit, which contradicts the passage''s emphasis on focusing effort into specific neighborhood projects. "Restrained" means to hold back or suppress, which is the opposite of what the participants did with their enthusiasm.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FT2XM5', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'The fruit fly Drosophila melanogaster can detect and avoid environments containing parasitoid wasp pheromones even when no wasps are physically present. Researchers have shown that this avoidance behavior is mediated by a specific subset of olfactory neurons that respond exclusively to wasp-derived chemical signals. Notably, fruit flies reared in laboratory colonies with no wasp exposure for over 200 generations still exhibit this avoidance, suggesting that ________', $lyceon_json$[{"key":"A","text":"the avoidance behavior is genetically encoded rather than learned from environmental exposure."},{"key":"B","text":"laboratory-reared fruit flies have weaker olfactory responses than wild populations."},{"key":"C","text":"parasitoid wasps have co-evolved to suppress their pheromone output near fruit fly colonies."},{"key":"D","text":"fruit flies use visual cues in addition to olfactory signals to detect wasp presence."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that fruit flies with no wasp exposure for over 200 generations still avoid wasp pheromones, which logically implies the behavior is innate and genetically encoded rather than learned. The claim that laboratory flies have weaker olfactory responses contradicts the passage''s finding that they still exhibit the avoidance behavior. The suggestion about wasps co-evolving to suppress pheromones introduces information entirely outside the passage''s scope. The mention of visual cues contradicts the passage''s focus on olfactory neurons as the mediating mechanism.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FTZ16R', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the text, what does the word "plastic" most nearly mean?', E'Cognitive neuroscientist Dariush Mehrani has demonstrated that the auditory cortex remains remarkably plastic well into the seventh decade of life, provided that individuals engage in sustained musical training. His longitudinal study of 143 participants aged 61 to 74 showed measurable cortical reorganization after just fourteen months of structured violin instruction, challenging the long-held assumption that such neural remodeling is confined to early developmental windows.', $lyceon_json$[{"key":"A","text":"adaptable"},{"key":"B","text":"synthetic"},{"key":"C","text":"fragile"},{"key":"D","text":"rigid"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes the auditory cortex undergoing measurable cortical reorganization in older adults, demonstrating the brain''s capacity to change in response to training. "Adaptable" captures this meaning of being capable of modification. "Synthetic" refers to artificially manufactured material, which is incoherent when describing a biological brain region. "Fragile" means easily damaged or broken, but the passage emphasizes the cortex''s capacity for positive structural change, not vulnerability. "Rigid" means inflexible and unable to change, which directly contradicts the passage''s evidence of cortical reorganization in older adults.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2G4R1NT', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Marine biologists have long known that coral reefs support extraordinary biodiversity in tropical oceans. ______ recent surveys conducted near the Galápagos Islands have documented over 270 species of reef-dwelling fish, confirming the ecological richness of the region.', $lyceon_json$[{"key":"A","text":"Indeed,"},{"key":"B","text":"Nevertheless,"},{"key":"C","text":"Conversely,"},{"key":"D","text":"Meanwhile,"}]$lyceon_json$::jsonb, 'A', NULL, E'The second sentence provides specific evidence that supports the general claim in the first sentence about coral reefs supporting extraordinary biodiversity. "Indeed," correctly signals that the following information confirms and reinforces the preceding claim. "Nevertheless," incorrectly introduces a concession or contrast, which does not match the reinforcing relationship between the sentences. "Conversely," signals an opposite or contrasting point, but the second sentence aligns with rather than opposes the first. "Meanwhile," implies two simultaneous but separate events, which mischaracterizes the logical connection of evidence supporting a claim.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HWPILU', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The fennec fox, native to the Sahara Desert, _______ unusually large ears that dissipate heat and allow the animal to detect prey moving beneath the sand.', $lyceon_json$[{"key":"A","text":"have"},{"key":"B","text":"are having"},{"key":"C","text":"has"},{"key":"D","text":"having"}]$lyceon_json$::jsonb, 'C', NULL, E'The subject of the sentence is "The fennec fox," which is singular. The phrase "native to the Sahara Desert" is a parenthetical appositive set off by commas and does not change the number of the subject. The singular subject requires the singular verb "has." The choice "have" is a plural verb form that does not agree with the singular subject. The choice "are having" incorrectly uses a plural auxiliary and employs the progressive aspect, which is unnatural for describing a permanent physical characteristic. The choice "having" is a participle, not a finite verb, and would leave the sentence without a main verb, creating a fragment.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2I0BJR5', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the claim made in Text 1?', E'Text 1: Ornithologist Priya Nambiar contends that migratory shorebirds select stopover sites based primarily on the caloric density of available invertebrate prey. She points to the strong correlation between benthic biomass measurements and shorebird stopover duration at 23 tidal flat sites along the East Asian–Australasian Flyway.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2I0ZH6Q', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the text, what does the word "temper" most nearly mean?', E'The metallurgist Elara Voss argued that industrial alloy designers must temper their reliance on computational models with hands-on experimentation, noting that simulations frequently fail to capture the microstructural irregularities that emerge during actual fabrication at high temperatures.', $lyceon_json$[{"key":"A","text":"moderate"},{"key":"B","text":"harden"},{"key":"C","text":"inflame"},{"key":"D","text":"dissolve"}]$lyceon_json$::jsonb, 'A', NULL, E'Voss argues that designers should balance their dependence on computational models by also doing hands-on work. "Moderate" fits because it means to reduce the intensity or extremity of something, here meaning to balance excessive reliance. "Harden" is a metallurgical meaning of temper (heat-treating metal), but the passage uses "temper" to describe adjusting a behavioral tendency, not physically treating material. "Inflame" means to intensify or provoke, which contradicts Voss''s argument for restraining reliance on simulations. "Dissolve" means to break apart or eliminate entirely, but Voss advocates balancing computational models with experimentation, not abandoning them.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LAPZE0', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Neither the lead architect nor the two junior associates who prepared the revised blueprints _______ that the ventilation calculations contained a unit-conversion error until the building inspector flagged it during the final walkthrough.', $lyceon_json$[{"key":"A","text":"realizes"},{"key":"B","text":"was realizing"},{"key":"C","text":"has realized"},{"key":"D","text":"realized"}]$lyceon_json$::jsonb, 'D', NULL, E'The subject uses a "neither...nor" construction, which requires the verb to agree with the nearer subject — in this case, "the two junior associates," which is plural. The sentence is set in the past ("until the building inspector flagged it"), so the simple past tense "realized" is correct: it is both plural-compatible and consistent with the past time frame. The choice "realizes" is singular present tense, failing on both number agreement with the nearer plural subject and tense consistency. The choice "was realizing" uses a singular auxiliary ("was") that does not agree with the plural nearer subject "associates." The choice "has realized" uses a singular auxiliary ("has") and the present perfect tense, failing on both number agreement and tense consistency with the past-tense narrative.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LSX8H1', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In 1987, archaeologist Payson Sheets discovered an ancient village buried under volcanic ash in present-day El _______ unlike most Mesoamerican excavations, this site preserved organic materials such as woven mats and stored grain.', $lyceon_json$[{"key":"A","text":"Salvador,"},{"key":"B","text":"Salvador;"},{"key":"C","text":"Salvador"},{"key":"D","text":"Salvador:"}]$lyceon_json$::jsonb, 'B', NULL, E'The sentence contains two independent clauses: one about Sheets discovering the village and one contrasting this site with most Mesoamerican excavations. A semicolon correctly separates two closely related independent clauses. A comma after "Salvador" creates a comma splice because the word "unlike" here introduces a new independent clause with its own subject and verb ("this site preserved"), not a dependent element. Omitting punctuation entirely produces a run-on sentence. A colon would be appropriate only if the second clause explained or elaborated on the first, but the second clause introduces a contrast rather than an explanation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SO9MWZ', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing a brief report on the tardigrade''s resilience and wants to introduce the organism to readers who are unfamiliar with it. Which choice most effectively accomplishes this goal?
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TWHZOJ', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Researchers at the University of Tromsø have found that Arctic bumblebees (Bombus polaris) maintain thoracic temperatures of 38°C even in ambient conditions as cold as 2°C. The bees accomplish this by decoupling their flight muscles from their wings and vibrating them rapidly, a process known as thermogenic shivering. This mechanism allows B. polaris to forage on early-blooming saxifrage when most other pollinators remain dormant, giving the species a competitive advantage in nutrient-scarce tundra ecosystems.', $lyceon_json$[{"key":"A","text":"Arctic bumblebees rely on a unique thermoregulation strategy that enables them to forage in extreme cold."},{"key":"B","text":"Thermogenic shivering is a process found across all bumblebee species inhabiting cold climates."},{"key":"C","text":"Saxifrage plants depend on Arctic bumblebees for pollination during the early spring."},{"key":"D","text":"Researchers at the University of Tromsø study insect physiology in tundra ecosystems."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage centers on how Arctic bumblebees use thermogenic shivering to maintain high body temperatures in freezing conditions, which lets them forage when competitors cannot. The option stating that Arctic bumblebees rely on a unique thermoregulation strategy to forage in extreme cold captures this central idea. The claim that thermogenic shivering is found across all cold-climate bumblebees extends beyond what the passage states, which discusses only B. polaris. The suggestion that saxifrage depends on these bees reverses the relationship described: the passage says the bees forage on saxifrage, not that the plant requires them. The option about researchers studying insect physiology names a true but peripheral detail rather than the passage''s main point.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TYIX13', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'Architect Lina Bo Bardi incorporated raw concrete and exposed structural elements into her designs, embracing an aesthetic that rejected ornamental excess. ______ she insisted on integrating lush tropical gardens and open-air walkways into her buildings, ensuring that inhabitants remained connected to the natural landscape surrounding them.', $lyceon_json$[{"key":"A","text":"In other words,"},{"key":"B","text":"At the same time,"},{"key":"C","text":"For instance,"},{"key":"D","text":"As a result,"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage describes two coexisting but seemingly disparate aspects of Bo Bardi''s design philosophy: rejecting ornamental excess while also insisting on natural elements like gardens and walkways. "At the same time," correctly signals that the second design choice existed alongside the first, capturing the simultaneity of two parallel commitments. "In other words," would indicate a restatement of the previous idea, but the second sentence introduces a distinct complementary practice rather than restating the first. "For instance," would signal an example illustrating the previous claim, but integrating gardens is not an example of rejecting ornamental excess — it is a separate design principle. "As a result," implies a causal consequence, but incorporating gardens does not logically follow from rejecting ornamentation; these are coexisting commitments rather than cause and effect.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2V7F1P3', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Which choice best describes the relationship between Text 1 and Text 2?', E'Text 1: Geochemist Halima Osei proposes that the elevated iridium concentrations found in late Devonian marine sediments indicate a bolide impact event comparable in scale to the end-Cretaceous asteroid strike. She argues that this impact was the principal trigger of the Kellwasser extinction event approximately 372 million years ago, citing the global uniformity of the iridium anomaly across seven stratigraphic sections on four continents.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WTT82V', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The grant committee reviewed proposals from fourteen research teams, ultimately _______ the award to the group whose methodology the external reviewers judged to be the most rigorous.', $lyceon_json$[{"key":"A","text":"giving"},{"key":"B","text":"gave"},{"key":"C","text":"had given"},{"key":"D","text":"gives"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence already has a main finite verb, "reviewed." The blank follows "ultimately" and introduces a participial phrase that adds supplementary information about what the committee did as part of the reviewing process. The present participle "giving" correctly forms this participial phrase, parallel to how the committee "reviewed... ultimately giving." The choice "gave" is a finite verb that would create a comma splice or a run-on, since two independent clauses ("reviewed" and "gave") cannot be joined by only a comma. The choice "had given" is also a finite verb in the past perfect tense, which would similarly create a sentence boundary error and illogically place the giving before the reviewing. The choice "gives" is a finite verb in the present tense, which would both create a boundary error and introduce a tense inconsistency with the past-tense "reviewed."', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XA2X2Z', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Based on the texts, which choice best describes how Lindqvist would most likely characterize Padmanabhan''s interpretation of the experimental results?', E'Text 1: Neurolinguist Ananya Padmanabhan conducted a priming experiment in which bilingual Kannada-English speakers were presented with Kannada sentences containing structurally ambiguous relative clauses. She found that participants resolved the ambiguities significantly faster when they had been primed with English sentences exhibiting the same attachment pattern, and she interpreted this as evidence that bilinguals maintain a shared syntactic workspace — a unified parsing architecture that operates across both languages simultaneously.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YHCL80', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Researchers at the Jodrell Bank Observatory have identified a repeating fast radio burst originating from a dwarf galaxy roughly three billion light-years _______ the signal, which arrives in irregular clusters, has defied every astrophysical model proposed to explain it.', $lyceon_json$[{"key":"A","text":"away;"},{"key":"B","text":"away,"},{"key":"C","text":"away"},{"key":"D","text":"away:"}]$lyceon_json$::jsonb, 'A', NULL, E'Two independent clauses appear here: one about the observatory identifying the radio burst and one about the signal defying astrophysical models. A semicolon correctly separates two closely related independent clauses. A comma after "away" creates a comma splice, because "the signal" begins a new independent clause with its own subject and verb. Omitting punctuation entirely produces a run-on sentence. A colon after "away" would require the second clause to explain, define, or elaborate on the first, but the second clause introduces new information about the signal''s behavior rather than clarifying the burst''s origin.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZZ2PD4', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The ceramic artist Lucie Rie, who fled Vienna in 1938 and eventually settled in _______ was not widely recognized in Britain until a 1967 retrospective at the Arts Council Gallery brought her austere, thin-walled vessels to public attention.', $lyceon_json$[{"key":"A","text":"London."},{"key":"B","text":"London,"},{"key":"C","text":"London;"},{"key":"D","text":"London"}]$lyceon_json$::jsonb, 'B', NULL, E'The clause "who fled Vienna in 1938 and eventually settled in London" is a nonrestrictive relative clause set off by commas. Because the opening comma appears before "who," a closing comma is required after "London" to properly close the parenthetical before the main clause resumes with "was not widely recognized." A period after "London" severs the sentence, leaving "was not widely recognized..." as a fragment with no subject. A semicolon after "London" incorrectly treats the nonrestrictive clause as an independent clause and also strands the remainder as a fragment. Omitting punctuation entirely fails to close the nonrestrictive clause, creating a grammatical error in the sentence structure.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
